114	                                // Some uploads groups doesn't contain channel button.
115	                                // Use data from first item instead.
116	                                if (group.getChannelId() == null) {
117	                                    List<MediaItem> mediaItems = group.getMediaItems();
118	
119	                                    // Filter collaborative content
120	                                    MediaItem first = Helpers.findFirst(mediaItems, mediaItem -> Helpers.startsWith(mediaItem.getAuthor(), mVideo.getAuthor()));
121	
122	                                    if (first == null && mediaItems != null && !mediaItems.isEmpty()) {
123	                                        first = mediaItems.get(0);
124	                                    }
125	
126	                                    if (first != null) {
127	                                        mServiceManager.loadMetadata(first, metadata -> {
128	                                            unsubscribe(metadata.getChannelId());
129	                                            mVideo.channelId = metadata.getChannelId();
130	                                        });
131	                                    }
132	
133	                                    return;
134	                                }
135	
136	                                unsubscribe(group.getChannelId());
137	                                mVideo.channelId = group.getChannelId();
138	                            });
139	                }));
