252	    private void processNextChannel(MediaServiceManager serviceManager, Iterator<MediaItem> iterator) {
253	        if (iterator.hasNext()) {
254	            MediaItem next = iterator.next();
255	
256	            if (!next.hasNewContent()) {
257	                processNextChannel(serviceManager, iterator);
258	                return;
259	            }
260	
261	            MessageHelpers.showMessage(getContext(), next.getTitle());
262	            serviceManager.loadChannelUploads(next, (groupTmp) -> processNextChannel(serviceManager, iterator));
263	        } else {
264	            MessageHelpers.showMessage(getContext(), R.string.msg_done);
265	        }
266	    }
